#include "stdafx.h"#include "HcdElementBase.h"struct SSCB_P{#include "PrivateVars/SCB.h"};class KSCB : public KHcdElementBase  , protected SSCB_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _SCB("SCB", KSCB::Create);IHcdElement *KSCB::Create(){  return new KSCB;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KSCB, 4 )void KSCB::InitParm(){#include "PrivateVars/SCB.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KSCB::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KSCB::StepCalc( SStepCalcParams &params ){  OUTD0 = ( INU0 * ScaleFactor ) + Bias;}